279:   const POST_FRAG = `#version 300 es
280:   precision highp float;
281:   uniform sampler2D uScene;
282:   uniform vec2  uRes;
283:   uniform float uTime;
284:   uniform float uHorizon;
285:   uniform float uLightning;
286:   out vec4 outColor;
287:   ${COMMON}
288:   vec3 aces(vec3 x){
289:     return clamp((x * (2.51 * x + 0.03)) / (x * (2.43 * x + 0.59) + 0.14), 0.0, 1.0);
290:   }
291:   void main(){
292:     vec2 uv = gl_FragCoord.xy / uRes;
293:     vec4 base = texture(uScene, uv);
294:     vec3 col = base.rgb;
295:     float wet = base.a;
296: 
297:     if (wet > 0.015){
298:       vec2 ruv = vec2(uv.x, uHorizon * 2.0 - uv.y);
299:       float rip = noise(vec2(uv.x * 210.0, uv.y * 130.0 + uTime * 5.0)) - 0.5;
300:       ruv.x += rip * 0.0035 * clamp((uv.y - uHorizon) * 4.0, 0.0, 1.0);
301:       ruv.y += rip * 0.0018;
302:       ruv = clamp(ruv, vec2(0.002), vec2(0.998));
303:       vec3 refl;
304:       refl.r = texture(uScene, clamp(ruv + vec2(0.0013, 0.0), vec2(0.002), vec2(0.998))).r;
305:       refl.g = texture(uScene, ruv).g;
306:       refl.b = texture(uScene, clamp(ruv - vec2(0.0013, 0.0), vec2(0.002), vec2(0.998))).b;
307:       col = mix(col, refl * 0.82 + vec3(0.008, 0.011, 0.012), wet * 0.62);
308:     }
309: 
310:     vec2 d = uv - 0.5;
311:     float ca = dot(d, d) * 0.0035;
312:     col.r = mix(col.r, texture(uScene, clamp(uv + d * ca, vec2(0.001), vec2(0.999))).r, 0.55);
313:     col.b = mix(col.b, texture(uScene, clamp(uv - d * ca, vec2(0.001), vec2(0.999))).b, 0.55);
314: 
315:     vec3 bloom = vec3(0.0);
316:     for (int i = 0; i < 8; i++){
317:       float a = float(i) * 0.785398 + 0.4;
318:       float r = 0.006 + 0.004 * float((i + 1) % 3);
319:       vec3 s = texture(uScene, clamp(uv + vec2(cos(a), sin(a)) * r, vec2(0.001), vec2(0.999))).rgb;
320:       bloom += max(s - vec3(0.66), vec3(0.0));
321:     }
322:     col += bloom * 0.15;
323: 
324:     float vig = smoothstep(0.92, 0.28, length(d * vec2(1.05, 1.18)));
325:     col *= mix(0.66, 1.0, vig);
326:     col *= 1.04;
327:     col = aces(col * 1.38);
328:     col = pow(col, vec3(0.88));
329:     float luma = dot(col, vec3(0.299, 0.587, 0.114));
330:     vec3 grade = mix(vec3(0.80, 0.95, 1.05), vec3(1.07, 1.00, 0.88), smoothstep(0.06, 0.62, luma));
331:     col = mix(vec3(luma), col, 1.08) * grade;
332:     col += vec3(0.45, 0.53, 0.62) * uLightning * 0.09;
333: 
334:     float grain = hash12(gl_FragCoord.xy + fract(uTime) * 431.0);
335:     col += (grain - 0.5) * 0.030;
336:     col += (hash12(gl_FragCoord.xy * 1.37) - 0.5) * 0.010;
337:     outColor = vec4(clamp(col, 0.0, 1.0), 1.0);
338:   }
339:   `;
